export function requireAuth(auth: AuthService, token: string): HandlerResult {
  const result = auth.authenticateUser("user", token);
  if (!result.ok) {
    return { ok: false, status: 401, body: { error: "unauthorized" } };
  }
  return { ok: true, status: 200 };
}

